INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT139-S4-Q2$batch11$, 139, 4, 2, $batch11$Must Be True$batch11$, $batch11$For house painting, acrylic paints are an excellent choice. They provide everything that a good paint should provide: smooth and even coverage, quick drying time, durability, and easy cleanup. Even acrylics, however, cannot correct such surface defects as badly cracked paint. Such conditions indicate some underlying problem, such as water damage, that needs repair.$batch11$, $batch11$Which one of the following is most strongly supported by the statements above?$batch11$, $batch11$D$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=139 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT139-S4-Q2$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$Badly cracked paint is not a result of harsh weather conditions.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT139-S4-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$Acrylics are the only paints that provide everything that most homeowners need from a paint.$batch11$, $batch11$Too Strong$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT139-S4-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$Acrylics should not be used to paint over other types of house paint.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT139-S4-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$It is not a requirement of house paints that they correct surface defects such as badly cracked paint.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT139-S4-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$Acrylic paints come in as wide a range of colors as do any other paints.$batch11$, $batch11$Unsupported$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT139-S4-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT139-S4-Q2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Acrylics provide everything a good paint should provide. Even acrylics can't correct defects like badly cracked paint. Those defects point to an underlying problem that needs repair.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Put the first two statements together. Acrylics give everything a good paint should. Acrylics can't fix cracked paint. So fixing cracked paint is not something a good paint must do.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Correcting surface defects is not a requirement of house paint.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT139-S4-Q2$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Water damage is one example of an underlying cause. Harsh weather could be another.$batch11$), ($batch11$B$batch11$, $batch11$Acrylics provide everything a good paint should, but other paints might too.$batch11$), ($batch11$C$batch11$, $batch11$Painting over other paint types never comes up.$batch11$), ($batch11$D$batch11$, $batch11$Acrylics meet every requirement of a good paint and still can't fix cracks. So fixing cracks isn't a requirement.$batch11$), ($batch11$E$batch11$, $batch11$Color range never comes up.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT139-S4-Q2$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
